import { add2, rotate2 } from "#core/scripts/MathHelpers.js";

import * as globals from "#base/maps/map-globals.js";
import { kdTree } from "#base/scripts/kd-tree.js";
import { RandomImpl } from "#base/scripts/random-pcg-32.js";
import { LandmassRegion } from "#base/scripts/voronoi-region.js";
import {
	BiomeType,
	ConfigValueRecord,
	FeatureType,
	isWater,
	ParameterSpecGroup,
	ParameterSpecNode,
	ParameterSpecRecord,
	RegionType,
	TerrainType,
} from "#base/scripts/voronoi-types.js";
import { RegionCell, VoronoiUtils } from "#base/scripts/voronoi-utils.js";

export enum SeparationFilterOptions {
	OFF = 0b000,
	DIFFERENT_LANDMASSES = 0b001,
	DIFFERENT_LANDMASS_GROUPS = 0b010,
	DIFFERENT_TYPES = 0b100,

	ALL = DIFFERENT_LANDMASSES | DIFFERENT_LANDMASS_GROUPS | DIFFERENT_TYPES,
}

export enum RemoveBridgingLandmassOptions {
	OFF,
	FORCE_COASTS,
	FORCE_OCEANS,
}

export class HexValidationSettings {
	polarMargin = 2;
	removeBridgingPlayerLandmasses: RemoveBridgingLandmassOptions = RemoveBridgingLandmassOptions.FORCE_OCEANS;
	forceCoasts = true;
	removeLakes = true;
	removeOrphanCoastTiles = true; // coast tiles that are part of a set with no land
	lakeDensityAllowed = 0.03; // ratio of land tiles to lake tiles.
	maxLakeSize = 6;
	removeAdjacentVolcanos = true;
	rebuildPlayerLandmasses = true;
}

export class VoronoiValidationSettings {
	forceCoasts = SeparationFilterOptions.OFF;
	forceOceans = SeparationFilterOptions.ALL;
}

export class HexTile {
	pos: float2 = { x: 0, y: 0 };
	coord: float2 = { x: 0, y: 0 };
	playerLandmassId = -1; // used to identify a contiguous land mass where players are allowed to spawn. Used for separating distant and home lands. -1 for unassigned/Ocean, 0 for non-player lands, 1+ for landmasses.
	majorPlayerRegionId = -1; // a subdivision of player landmasses to denote a region where a single player may spawn. -1 for unassigned, 0+ for player region ids.
	terrainType: TerrainType = TerrainType.Unknown;
	biomeType: BiomeType = BiomeType.Unknown;
	featureType: FeatureType = FeatureType.None;
	visited = 0; // used during map creation and processing.

	isPassable(): boolean {
		return this.terrainType !== TerrainType.Ocean && this.terrainType !== TerrainType.Mountainous;
	}
}

export class HexTileDesc {
	playerLandmassId = -1;
	terrainType: TerrainType = TerrainType.Unknown;
	biomeType: BiomeType = BiomeType.Unknown;
	featureType: FeatureType = FeatureType.None;
}

export enum FloodFillResult {
	Include,
	Exclude,
	Halt,
}

export interface LandmassTiles {
	land: number;
	coast: number;
	playerLandmassId: number;
}

export class HexMapStats {
	oceanTileCount = 0;
	totalCoastCount = 0;
	totalLandCount = 0;
	playerLandmasses: LandmassTiles[] = [];
	nonPlayerLand: LandmassTiles = { land: 0, coast: 0, playerLandmassId: -1 };

	log() {
		console.log(`Ocean tiles: ${this.oceanTileCount}`);
		console.log(`Total coast tiles: ${this.totalCoastCount}`);
		console.log(`Total land tiles: ${this.totalLandCount}`);
		console.log(`Non-player lands: ${this.nonPlayerLand.land} land tiles, ${this.nonPlayerLand.coast} coast tiles`);
		for (let i = 0; i < this.playerLandmasses.length; ++i) {
			const landmass = this.playerLandmasses[i];
			console.log(`Player landmass ${i}: ${landmass.land} land tiles, ${landmass.coast} coast tiles`);
		}
	}
}

export interface LakeSettings extends ConfigValueRecord {
	lakeDensity: number; // ratio of land tiles to lake tiles.
	meanSize: number; // mean size of lakes in number of tiles.
	stdDevBelow: number; // standard deviation below the mean size for lake generation.
	stdDevAbove: number; // standard deviation above the mean size for lake generation.
	clumpiness: number; // how much lakes should clump together. 0 is no clumping, positive values cause lake tiles to clump together more, negative values cause lakes to be stringy.
}

export const lakeSettingsSchema = {
	label: "Lake Settings",
	children: {
		lakeDensity: {
			label: "Lake Density",
			description: "The ratio of land tiles to lake tiles.",
			default: 0.04,
			min: 0,
			max: 1,
			step: 0.001,
		},
		meanSize: {
			label: "Mean Size",
			description: "The mean size of lakes in number of tiles.",
			default: 3.8,
			min: 1,
			max: 20,
			step: 0.1,
		},
		stdDevBelow: {
			label: "Standard Deviation Below",
			description: "The standard deviation below the mean size for lake generation.",
			default: 1.8,
			min: 0,
			max: 10,
			step: 0.1,
		},
		stdDevAbove: {
			label: "Standard Deviation Above",
			description: "The standard deviation above the mean size for lake generation.",
			default: 0.8,
			min: 0,
			max: 10,
			step: 0.1,
		},
		clumpiness: {
			label: "Clumpiness",
			description:
				"How much lakes should clump together. 0 is no clumping, positive values cause lake tiles to clump together more, negative values cause lakes to be stringy.",
			default: -1.0,
			min: -5,
			max: 5,
			step: 0.1,
		},
	},
} as const satisfies ParameterSpecGroup;

export const hexMapSchema = {
	label: "Hex Generation Settings",
	children: {
		lakeSettings: lakeSettingsSchema,
	},
} as const satisfies ParameterSpecGroup;

function buildDefaultHexSettings(schema: ParameterSpecRecord): ConfigValueRecord {
	const out: ConfigValueRecord = {};
	for (const [key, node] of Object.entries(schema)) {
		if ("children" in node) {
			out[key] = buildDefaultHexSettings(node.children);
		} else {
			out[key] = node.default;
		}
	}
	return out;
}

export function getDefaultHexSettings(): ConfigValueRecord {
	return buildDefaultHexSettings(hexMapSchema.children);
}

// A representation of the current map in typescript memory. Can read from and to Game Core.
export class HexMap {
	private m_tiles: HexTile[][] = [];
	private m_wrappedXIndices: number[] = []; // Saves lots of % calls
	private m_xOffset = 0;
	private m_yOffset = 0;
	private m_validationSettings: HexValidationSettings = new HexValidationSettings();
	private m_lakeTiles = 0;

	private m_settings: ConfigValueRecord = getDefaultHexSettings();

	getSettings(): ConfigValueRecord {
		return this.m_settings;
	}

	setSettings(settings: ConfigValueRecord) {
		this.m_settings = settings;
	}

	setValidationSettings(validationSettings: HexValidationSettings) {
		this.m_validationSettings = validationSettings;
	}

	buildWrappedIndices(xCount: number) {
		if (this.m_wrappedXIndices.length != xCount * 3) {
			this.m_wrappedXIndices = Array.from({ length: xCount * 3 }, (_, index) => index % xCount);
		}
	}

	getSettingsSchema(): ParameterSpecNode {
		return hexMapSchema;
	}

	initFromRegionCells(
		width: number,
		height: number,
		tree: Readonly<kdTree<RegionCell>>,
		landmassRegions: readonly LandmassRegion[],
		playerRegionCallback: (cell: RegionCell) => number,
		voronoiValidationSettings?: VoronoiValidationSettings,
		dominantCells?: RegionCell[][], // maps x/y hex tiles to the region cell used for that tile.
	) {
		this.buildWrappedIndices(width);

		// Sample multiple points inside the hex and take the average - one sample in the center, and 6 around it.
		const offsetPoint: float2 = { x: 0.736 * 0.5, y: 0 };
		const offsetPoints: float2[] = [{ x: 0, y: 0 }];
		for (let i = 0; i < 6; ++i) {
			offsetPoints.push(rotate2(offsetPoint, (i * Math.PI) / 3));
		}

		class VoronoiHexTile {
			landmassId = -1;
			playerLandmassId = -1;
			terrainType: TerrainType = TerrainType.Unknown;
			biomeType: BiomeType = BiomeType.Unknown;
			featureType: FeatureType = FeatureType.None;
			landmassGroupId = -1;
			regionType = RegionType.None;
		}

		const voronoiHexTiles: VoronoiHexTile[][] = new Array<VoronoiHexTile[]>(height);

		const yOffset = 0.325;
		const halfSqrt3 = Math.sqrt(3) * 0.5;
		for (let y = 0; y < height; ++y) {
			voronoiHexTiles[y] = new Array<VoronoiHexTile>(width);
			const xOffset = y % 2 == 0 ? 0 : Math.sqrt(3) * 0.25;

			for (let x = 0; x < width; ++x) {
				const getRegionCellKey = (cell: RegionCell) => {
					return `${cell.terrainType},${cell.featureType}`;
				};

				const centerPos = { x: xOffset + x * halfSqrt3, y: yOffset + y * 0.75 };
				const regionCells = new Map<string, [number, RegionCell]>();

				for (const offsetPos of offsetPoints) {
					const samplePos = add2(offsetPos, centerPos);
					const regionCell: RegionCell | undefined = tree.search(samplePos)?.data;
					if (regionCell) {
						const regionCellKey = getRegionCellKey(regionCell);
						const entry = regionCells.get(regionCellKey);
						if (entry) {
							entry[0]++;
						} else {
							regionCells.set(regionCellKey, [1, regionCell]);
						}
					}
				}

				// Need to add together cells from the same region.
				let dominantCell: RegionCell | null = null;
				let maxCount = 0;
				for (const [_key, [count, cell]] of regionCells) {
					if (count > maxCount) {
						dominantCell = cell;
						maxCount = count;
					}
				}

				const voronoiTile: VoronoiHexTile = new VoronoiHexTile();
				if (dominantCell) {
					voronoiTile.landmassId = dominantCell.landmassId;
					voronoiTile.playerLandmassId = playerRegionCallback(dominantCell);
					voronoiTile.terrainType = dominantCell.terrainType;
					voronoiTile.biomeType = dominantCell.biomeType;
					voronoiTile.featureType = dominantCell.featureType;
					voronoiTile.landmassGroupId = landmassRegions[dominantCell.landmassId].groupId;
					voronoiTile.regionType = landmassRegions[dominantCell.landmassId].type;

					if (dominantCells) {
						(dominantCells[x] ??= [])[y] = dominantCell; // save the dominant cell for this tile, for use in later processing if needed.
					}
				} else {
					console.error("No region cell found for hex at " + x + "," + y);
				}
				voronoiHexTiles[y][x] = voronoiTile;
			}
		}

		// Check to see if separation needs to be forced between different landmasses, landmass groups, or region types.

		const shouldSeparateByFilter = (
			tile: VoronoiHexTile,
			neighbor: VoronoiHexTile,
			filter: SeparationFilterOptions,
		): boolean => {
			return (
				((filter & SeparationFilterOptions.DIFFERENT_LANDMASSES) !== 0 &&
					neighbor.landmassId !== tile.landmassId) ||
				((filter & SeparationFilterOptions.DIFFERENT_LANDMASS_GROUPS) !== 0 &&
					neighbor.landmassGroupId !== tile.landmassGroupId) ||
				((filter & SeparationFilterOptions.DIFFERENT_TYPES) !== 0 && neighbor.regionType !== tile.regionType)
			);
		};

		const applyTerrainSeparation = (
			filter: SeparationFilterOptions,
			targetTerrain: TerrainType,
			shouldProcessTile: (terrainType: TerrainType) => boolean,
		) => {
			if (filter === SeparationFilterOptions.OFF) {
				return;
			}

			for (let y = 0; y < voronoiHexTiles.length; ++y) {
				for (let x = 0; x < voronoiHexTiles[y].length; ++x) {
					const tile = voronoiHexTiles[y][x];
					if (!shouldProcessTile(tile.terrainType)) {
						continue;
					}
					if (
						this.anyNeighborOfArr(
							x,
							y,
							voronoiHexTiles,
							(neighbor) =>
								neighbor !== undefined &&
								shouldProcessTile(neighbor.terrainType) &&
								shouldSeparateByFilter(tile, neighbor, filter),
						)
					) {
						tile.terrainType = targetTerrain;
					}
				}
			}
		};

		console.log("Applying terrain separation for coasts...");
		applyTerrainSeparation(
			voronoiValidationSettings?.forceCoasts ?? SeparationFilterOptions.OFF,
			TerrainType.Coast,
			(terrainType) => terrainType !== TerrainType.Ocean && terrainType !== TerrainType.Coast,
		);

		console.log("Applying terrain separation for oceans...");
		applyTerrainSeparation(
			voronoiValidationSettings?.forceOceans ?? SeparationFilterOptions.OFF,
			TerrainType.Ocean,
			(terrainType) => terrainType !== TerrainType.Ocean,
		);

		this.initFromTiles(width, height, (x: number, y: number, _centerPos: float2) => voronoiHexTiles[y][x]);
	}

	initFromTiles(xCount: number, yCount: number, getTile: (x: number, y: number, pos: float2) => HexTileDesc) {
		this.buildWrappedIndices(xCount);

		this.m_tiles = new Array<HexTile[]>(yCount);

		const yOffset = 0.325;
		for (let y = 0; y < yCount; ++y) {
			const xOffset = y % 2 == 0 ? 0 : Math.sqrt(3) * 0.25;
			this.m_tiles[y] = new Array<HexTile>(xCount); // create the row.
			for (let x = 0; x < xCount; ++x) {
				const centerPos = { x: xOffset + x * Math.sqrt(3) * 0.5, y: yOffset + y * 0.75 };
				const tileDesc = getTile(x, y, centerPos);
				const tile = new HexTile();
				tile.coord = { x, y };
				tile.pos = centerPos;
				Object.assign(tile, tileDesc);
				this.m_tiles[y][x] = tile;
			}
		}
	}

	initFromTerrainBuilder() {
		const iWidth = GameplayMap.getGridWidth();
		const iHeight = GameplayMap.getGridHeight();
		this.buildWrappedIndices(iWidth);

		// TODO: can we avoid these conversions and use the gamecore types? maybe there's a way to expose them as enums.
		// TODO: Need to handle volcanoes, maybe now's the time to add a feature type to the hex tiles?
		const convertTerrainType = (terrainType: globalThis.TerrainType): TerrainType => {
			switch (terrainType) {
				case globals.g_OceanTerrain:
					return TerrainType.Ocean;
				case globals.g_CoastTerrain:
					return TerrainType.Coast;
				case globals.g_FlatTerrain:
					return TerrainType.Flat;
				case globals.g_HillTerrain:
					return TerrainType.Rough;
				case globals.g_MountainTerrain:
					return TerrainType.Mountainous;
				case globals.g_NavigableRiverTerrain:
					return TerrainType.NavRiver;
			}
			return TerrainType.Unknown; // default fallback, shouldn't happen.
		};

		const convertBiomeType = (biomeType: globalThis.BiomeType): BiomeType => {
			switch (biomeType) {
				case globals.g_MarineBiome:
					return BiomeType.Ocean;
				case globals.g_DesertBiome:
					return BiomeType.Desert;
				case globals.g_GrasslandBiome:
					return BiomeType.Grassland;
				case globals.g_PlainsBiome:
					return BiomeType.Plains;
				case globals.g_TropicalBiome:
					return BiomeType.Tropical;
				case globals.g_TundraBiome:
					return BiomeType.Tundra;
			}
			return BiomeType.Unknown; // default fallback, shouldn't happen.
		};

		const convertFeatureType = (featureType: globalThis.FeatureType): FeatureType => {
			switch (featureType) {
				case globals.g_VolcanoFeature:
					return FeatureType.Volcano;
			}
			return FeatureType.None;
		};

		this.initFromTiles(iWidth, iHeight, (x, y, _pos) => {
			const hexTileDesc: HexTileDesc = new HexTileDesc();
			hexTileDesc.playerLandmassId = GameplayMap.getLandmassRegionId(x, y);
			hexTileDesc.terrainType = convertTerrainType(GameplayMap.getTerrainType(x, y));
			hexTileDesc.biomeType = convertBiomeType(GameplayMap.getBiomeType(x, y));
			hexTileDesc.featureType = convertFeatureType(GameplayMap.getFeatureType(x, y));
			return hexTileDesc;
		});
	}

	writeToTerrainBuilder() {
		for (let y = 0; y < this.m_tiles.length; ++y) {
			for (let x = 0; x < this.m_tiles[y].length; ++x) {
				const tile: HexTile = this.m_tiles[y][x];
				if (tile.playerLandmassId === 0) {
					TerrainBuilder.addPlotTag(x, y, PlotTags.PLOT_TAG_ISLAND);
					TerrainBuilder.setLandmassRegionId(x, y, 0);
				} else {
					TerrainBuilder.setLandmassRegionId(x, y, tile.playerLandmassId);
				}

				const terrainType = (() => {
					switch (tile.terrainType) {
						case TerrainType.Flat:
							return globals.g_FlatTerrain;
						case TerrainType.Mountainous:
							return globals.g_MountainTerrain;
						case TerrainType.Rough:
							return globals.g_HillTerrain;
						case TerrainType.Ocean:
							return globals.g_OceanTerrain;
						case TerrainType.Coast:
							return globals.g_CoastTerrain;
						default:
							return globals.g_FlatTerrain; // default fallback, shouldn't happen.
					}
				})();

				TerrainBuilder.setTerrainType(x, y, terrainType);
				if (tile.featureType === FeatureType.Volcano) {
					TerrainBuilder.setFeatureType(x, y, {
						Feature: globals.g_VolcanoFeature,
						Direction: -1,
						Elevation: 0,
					});
				}
			}
		}
		this.getMapStats().log();
	}

	consolePrintMap(tiles: { terrainType: TerrainType }[][]) {
		for (let y = tiles.length - 1; y >= 0; --y) {
			let line = "";
			for (const tile of tiles[y]) {
				line +=
					tile.terrainType === TerrainType.Ocean
						? "."
						: tile.terrainType === TerrainType.Coast
							? "~"
							: tile.terrainType.toString();
			}
			console.log(line);
		}
	}

	EvenRowDeltas: [number, number][] = [
		[0, -1],
		[1, 0],
		[0, 1],
		[-1, 1],
		[-1, 0],
		[-1, -1],
	];

	OddRowDeltas: [number, number][] = [
		[1, -1],
		[1, 0],
		[1, 1],
		[0, 1],
		[-1, 0],
		[0, -1],
	];

	forNeighbors<T = HexTile>(x: number, y: number, sourceArray: readonly T[][], callback: (neighbor: T) => void) {
		const deltas = y % 2 === 0 ? this.EvenRowDeltas : this.OddRowDeltas;
		for (const [dx, dy] of deltas) {
			const ny = y + dy;
			if (ny < 0 || ny >= sourceArray.length) continue;
			const nx = x + dx + sourceArray[0].length;
			const neighbor = sourceArray[ny][this.m_wrappedXIndices[nx]];
			if (neighbor) {
				callback(neighbor);
			}
		}
	}

	getNeighborsOfArr<T = HexTile>(neighbors: T[], x: number, y: number, sourceArr: readonly T[][]) {
		this.forNeighbors(x, y, sourceArr, (neighbor) => {
			neighbors.push(neighbor as T);
		});
	}

	getNeighborsOfArrFiltered<T = HexTile>(
		neighbors: T[],
		x: number,
		y: number,
		sourceArr: readonly T[][],
		condition: (neighbor: T) => boolean,
	) {
		this.forNeighbors(x, y, sourceArr, (neighbor) => {
			if (condition(neighbor as T)) {
				neighbors.push(neighbor as T);
			}
		});
	}

	appendNeighbors(tile: HexTile, list: HexTile[], condition: (neighbor: HexTile) => boolean) {
		this.getNeighborsOfArrFiltered(list, tile.coord.x, tile.coord.y, this.m_tiles, condition);
	}

	anyNeighborOfArr<T = HexTile>(
		x: number,
		y: number,
		sourceArr: readonly T[][],
		condition: (neighbor: T) => boolean,
	): boolean {
		const deltas = y % 2 === 0 ? this.EvenRowDeltas : this.OddRowDeltas;
		for (const [dx, dy] of deltas) {
			const ny = y + dy;
			if (ny < 0 || ny >= sourceArr.length) continue;
			const nx = x + dx + sourceArr[0].length;
			const neighbor = sourceArr[ny][this.m_wrappedXIndices[nx]];
			if (neighbor && condition(neighbor)) {
				return true;
			}
		}
		return false;
	}

	anyNeighbor(tile: HexTile, condition: (neighbor: HexTile) => boolean): boolean {
		return this.anyNeighborOfArr(tile.coord.x, tile.coord.y, this.m_tiles, condition);
	}

	forAllTiles(callback: (tile: HexTile) => void) {
		for (const row of this.m_tiles) {
			for (const tile of row) {
				callback(tile);
			}
		}
	}

	// #######################
	// Validation
	// #######################

	validate() {
		if (this.m_validationSettings.polarMargin > 0) {
			this.validatePoles(this.m_validationSettings.polarMargin);
		}
		if (this.m_validationSettings.removeBridgingPlayerLandmasses != RemoveBridgingLandmassOptions.OFF) {
			this.removeBridgingPlayerLandmasses(this.m_validationSettings.removeBridgingPlayerLandmasses);
		}
		if (this.m_validationSettings.forceCoasts) {
			this.validateCoasts();
		}
		if (this.m_validationSettings.removeLakes) {
			this.removeLakes();
		}
		if (this.m_validationSettings.removeOrphanCoastTiles) {
			this.removeOrphanCoastTiles();
		}
		if (this.m_validationSettings.removeAdjacentVolcanos) {
			this.removeAdjacentVolcanoes();
		}
		if (this.m_validationSettings.rebuildPlayerLandmasses) {
			this.rebuildPlayerLandmasses();
		}
	}

	getMapStats(): HexMapStats {
		const stats: HexMapStats = new HexMapStats();
		for (const tile of this.m_tiles.flat()) {
			if (tile.terrainType === TerrainType.Ocean) {
				stats.oceanTileCount++;
			} else {
				const tileCount: LandmassTiles =
					tile.playerLandmassId <= 0
						? stats.nonPlayerLand
						: (stats.playerLandmasses[tile.playerLandmassId - 1] ??= {
								land: 0,
								coast: 0,
								playerLandmassId: tile.playerLandmassId,
							});
				if (tile.terrainType === TerrainType.Coast) {
					tileCount.coast++;
					stats.totalCoastCount++;
				} else {
					tileCount.land++;
					stats.totalLandCount++;
				}
			}
		}

		return stats;
	}

	validatePoles(marginSize: number) {
		for (let y = 0; y < marginSize; ++y) {
			for (const tile of this.m_tiles[y]) {
				tile.terrainType = TerrainType.Ocean;
				tile.playerLandmassId = -1;
			}
		}
		for (let y = this.m_tiles.length - marginSize; y < this.m_tiles.length; ++y) {
			for (const tile of this.m_tiles[y]) {
				tile.terrainType = TerrainType.Ocean;
				tile.playerLandmassId = -1;
			}
		}
	}

	validateCoasts() {
		this.forAllTiles((tile: HexTile) => {
			if (tile.terrainType !== TerrainType.Ocean && tile.terrainType !== TerrainType.Coast) {
				this.forNeighbors(tile.coord.x, tile.coord.y, this.m_tiles, (neighbor) => {
					if (neighbor && neighbor.terrainType === TerrainType.Ocean) {
						neighbor.terrainType = TerrainType.Coast;
						neighbor.playerLandmassId = tile.playerLandmassId;
					}
				});
			}
		});
	}

	removeLakes() {
		const lakes: { tiles: HexTile[]; landmassId: number }[] = [];
		let totalLakeTiles = 0;
		let totalLandTiles = 0;
		this.forAllTiles((tile: HexTile) => {
			if (tile.terrainType !== TerrainType.Ocean && tile.terrainType !== TerrainType.Coast) {
				++totalLandTiles;
			} else if (tile.terrainType === TerrainType.Coast && !tile.visited) {
				let foundOcean = false;
				let playerLandmassId = 0;
				const lakeTiles: HexTile[] = [];
				this.floodFill(tile, (tile: HexTile): FloodFillResult => {
					if (tile.terrainType === TerrainType.Coast) {
						lakeTiles.push(tile);
						return FloodFillResult.Include;
					} else if (tile.terrainType === TerrainType.Ocean) {
						foundOcean = true;
					} else if (tile.terrainType === TerrainType.Flat) {
						playerLandmassId = tile.playerLandmassId;
					}
					return FloodFillResult.Exclude;
				});
				if (!foundOcean) {
					lakes.push({ tiles: lakeTiles, landmassId: playerLandmassId });
					totalLakeTiles += lakeTiles.length;
				}
			}
		});
		this.clearVisited();
		const lakeRatio = totalLakeTiles / totalLandTiles;
		console.log(
			`Found ${lakes.length} lakes with a total of ${totalLakeTiles} tiles. Ratio is ${(lakeRatio * 100).toFixed(2)}%.`,
		);
		lakes.sort((a, b) => b.tiles.length - a.tiles.length);
		for (const lake of lakes) {
			const ratioIfRemoved = (totalLakeTiles - lake.tiles.length) / totalLandTiles;
			if (
				ratioIfRemoved > this.m_validationSettings.lakeDensityAllowed ||
				lake.tiles.length > this.m_validationSettings.maxLakeSize
			) {
				for (const tile of lake.tiles) {
					tile.terrainType = TerrainType.Flat;
					tile.playerLandmassId = lake.landmassId;
				}
				totalLakeTiles -= lake.tiles.length;
			}
		}
		console.log(
			`After removal, total lake tiles: ${totalLakeTiles}, ratio: ${((totalLakeTiles / totalLandTiles) * 100).toFixed(2)}%.`,
		);
		this.m_lakeTiles = totalLakeTiles;
	}

	removeOrphanCoastTiles() {
		let totalRemovedTiles = 0;
		this.forAllTiles((tile: HexTile) => {
			if (tile.terrainType === TerrainType.Coast && !tile.visited) {
				const coastTiles: HexTile[] = [];
				let foundLand = false;

				this.floodFill(tile, (tile: HexTile): FloodFillResult => {
					if (tile.terrainType === TerrainType.Coast) {
						coastTiles.push(tile);
						return FloodFillResult.Include;
					} else if (tile.terrainType !== TerrainType.Ocean) {
						foundLand = true;
						return FloodFillResult.Halt;
					}
					return FloodFillResult.Exclude;
				});

				if (!foundLand) {
					for (const coastTile of coastTiles) {
						coastTile.terrainType = TerrainType.Ocean;
						coastTile.playerLandmassId = -1;
					}
					totalRemovedTiles += coastTiles.length;
				}
			}
		});
		this.clearVisited();
		console.log(`Removed ${totalRemovedTiles} orphan coast tiles.`);
	}

	removeAdjacentVolcanoes() {
		this.forAllTiles((tile: HexTile) => {
			if (tile.featureType === FeatureType.Volcano) {
				this.forNeighbors(tile.coord.x, tile.coord.y, this.m_tiles, (neighbor) => {
					if (neighbor?.featureType === FeatureType.Volcano) {
						tile.featureType = FeatureType.None;
					}
				});
			}
		});
	}

	// #######################
	// Additional Generation
	// #######################

	GenerateLakes() {
		const s_validSeed = 1;
		const s_considered = 2;
		const s_lake = 3;

		// Find all potential lake seed tiles - flat tiles that aren't adjacent to ocean or coast.
		const lakeSeedTiles: HexTile[] = [];
		let totalFlatTiles = 0;
		this.forAllTiles((tile: HexTile) => {
			if (tile.terrainType === TerrainType.Flat) {
				++totalFlatTiles;
				if (
					!this.anyNeighbor(
						tile,
						(neighbor) =>
							neighbor.terrainType === TerrainType.Ocean || neighbor.terrainType === TerrainType.Coast,
					)
				) {
					lakeSeedTiles.push(tile);
					tile.visited = s_validSeed;
				}
			}
		});

		const lakeSettings = this.m_settings["lakeSettings"] as LakeSettings;
		const targetLakeTileCount = Math.round(totalFlatTiles * lakeSettings.lakeDensity);

		let lakesAdded = 0;
		let lakeTilesAdded = 0;

		while (this.m_lakeTiles < targetLakeTileCount && lakeSeedTiles.length > 0) {
			// Pick a random tile, and choose a size, then grow the lake into adjacent tiles that have visited == 1, until we hit the size or run out of valid tiles.
			const seedIndex = RandomImpl.getRandomNumber(lakeSeedTiles.length, "Random Lake Seed");
			const seedTile: HexTile = VoronoiUtils.swapAndPop(lakeSeedTiles, seedIndex);
			if (seedTile.visited !== s_validSeed) {
				continue; // this tile was already considered as part of another lake.
			}
			const lakeSize = RandomImpl.randomNormal2(
				lakeSettings.meanSize,
				lakeSettings.stdDevBelow,
				lakeSettings.stdDevAbove,
				"Random Lake Size",
			);
			const totalSize = VoronoiUtils.clamp(Math.round(lakeSize), 0, 20);
			const considerTiles: HexTile[] = [seedTile];
			seedTile.visited = s_considered;

			const popWeightedLakeTile = (clumpiness: number): HexTile => {
				if (considerTiles.length == 1) {
					return considerTiles.pop()!;
				}

				// Score each tile by how many lake neighbors it has
				const weights: number[] = considerTiles.map((t) => {
					let lakeNeighborCount = 0;
					this.forNeighbors(t.coord.x, t.coord.y, this.m_tiles, (neighbor) => {
						if (neighbor.visited === s_lake) lakeNeighborCount++;
					});
					// clumpiness > 0 biases toward more lake neighbors, < 0 biases away
					return Math.pow(lakeNeighborCount, clumpiness);
				});

				const totalWeight = weights.reduce((a, b) => a + b, 0);
				let roll = (RandomImpl.getRandomNumber(1000, "Lake Clump Weight") / 1000) * totalWeight;
				for (let i = 0; i < weights.length; i++) {
					roll -= weights[i];
					if (roll <= 0) {
						return VoronoiUtils.swapAndPop(considerTiles, i);
					}
				}
				return considerTiles.pop()!;
			};

			let size = 0;
			const lakeTiles: float2[] = [];
			let lakePlayerLandmass = -1;
			while (totalSize > size && considerTiles.length > 0 && this.m_lakeTiles < targetLakeTileCount) {
				const tile = popWeightedLakeTile(lakeSettings.clumpiness);
				tile.visited = s_lake;
				tile.terrainType = TerrainType.Coast;
				lakeTiles.push(tile.coord);
				lakePlayerLandmass = tile.playerLandmassId;
				this.m_lakeTiles++;
				size++;

				let idx = considerTiles.length;
				this.appendNeighbors(tile, considerTiles, (neighbor) => neighbor.visited === s_validSeed);
				for (idx; idx < considerTiles.length; ++idx) {
					considerTiles[idx].visited = s_considered;
				}
			}
			console.log(
				`Added lake of size ${size} at ${seedTile.coord.x},${seedTile.coord.y} on landmass ${lakePlayerLandmass}. (${lakeTiles.map((t) => `(${t.x},${t.y})`).join(", ")})`,
			);
			++lakesAdded;
			lakeTilesAdded += size;
		}

		console.log(`Added ${lakesAdded} lakes with a total of ${lakeTilesAdded} tiles.`);

		this.clearVisited();
	}

	// #######################
	// Player region generation and landmass separation
	// #######################

	removeBridgingPlayerLandmasses(option: RemoveBridgingLandmassOptions) {
		this.forAllTiles((tile: HexTile) => {
			let checkTile = tile.terrainType !== TerrainType.Ocean;
			if (option === RemoveBridgingLandmassOptions.FORCE_COASTS) {
				checkTile = checkTile && tile.terrainType !== TerrainType.Coast;
			}

			if (checkTile) {
				if (
					this.anyNeighborOfArr(
						tile.coord.x,
						tile.coord.y,
						this.m_tiles,
						(neighbor) =>
							neighbor &&
							neighbor.playerLandmassId !== tile.playerLandmassId &&
							neighbor.playerLandmassId !== -1 &&
							(option != RemoveBridgingLandmassOptions.FORCE_COASTS ||
								neighbor.terrainType !== TerrainType.Coast),
					)
				) {
					tile.terrainType =
						option === RemoveBridgingLandmassOptions.FORCE_OCEANS ? TerrainType.Ocean : TerrainType.Coast;
					if (tile.terrainType === TerrainType.Ocean) {
						tile.playerLandmassId = -1;
					}
				}
			}
		});
	}

	rebuildPlayerLandmasses() {
		let nextPlayerLandmassId = 1;
		this.forAllTiles((tile: HexTile) => {
			if (tile.terrainType !== TerrainType.Ocean && tile.playerLandmassId > 0 && !tile.visited) {
				this.floodFill(tile, (tile: HexTile): FloodFillResult => {
					if (tile.terrainType === TerrainType.Ocean) {
						return FloodFillResult.Exclude;
					} else {
						tile.playerLandmassId = nextPlayerLandmassId;
						return FloodFillResult.Include;
					}
				});
				nextPlayerLandmassId++;
			}
		});
		this.clearVisited();
	}

	offset(x: number, y: number) {
		x = Math.round(x);
		y = Math.round(y);
		const xOffset = x - this.m_xOffset;
		const yOffset = y - this.m_yOffset;

		if (xOffset == 0 && yOffset == 0) {
			return;
		}

		const height: number = this.m_tiles.length;
		const width: number = height > 0 ? this.m_tiles[0].length : 0;

		const offsetTiles: HexTile[][] = new Array<HexTile[]>(height);
		for (let y = 0; y < height; ++y) {
			offsetTiles[y] = new Array<HexTile>(width); // create the row.
		}

		this.forAllTiles((tile) => {
			const xOffsetCoord = xOffset + tile.coord.x;
			const yOffsetCoord = yOffset + tile.coord.y;
			tile.coord.x = ((xOffsetCoord % width) + width) % width;
			tile.coord.y = ((yOffsetCoord % height) + height) % height;

			const xTileOffset = tile.coord.y % 2 == 0 ? 0 : Math.sqrt(3) * 0.25;
			tile.pos = { x: xTileOffset + tile.coord.x * Math.sqrt(3) * 0.5, y: 0.325 + tile.coord.y * 0.75 };
			offsetTiles[tile.coord.y][tile.coord.x] = tile;
		});

		this.m_tiles = offsetTiles;
		this.m_xOffset = ((x % width) + width) % width;
		this.m_yOffset = ((y % height) + height) % height;
	}

	getOffsetX() {
		return this.m_xOffset;
	}
	getOffsetY() {
		return this.m_yOffset;
	}

	alignToBestMeridian() {
		const height = this.m_tiles.length;
		const width = height > 0 ? this.m_tiles[0].length : 0;

		const scoreColumn = (xPos: number) => {
			let score = 0;
			for (const row of this.m_tiles) {
				const leftPos = (xPos - 1 + width) % width;
				score += isWater(row[xPos].terrainType) || isWater(row[leftPos].terrainType) ? 1 : 0;
			}
			return score;
		};

		let bestScore = 0;
		let bestColumn = 0;
		for (let x = 0; x < width; ++x) {
			const score = scoreColumn(x);
			if (score > bestScore) {
				bestColumn = x;
				bestScore = score;
			}
		}
		this.offset(this.m_xOffset - bestColumn, this.m_yOffset);
	}

	floodFill(initialTile: HexTile, considerCallback: (tile: HexTile) => FloodFillResult): HexTile[] {
		initialTile.visited = 1;
		if (considerCallback(initialTile) == FloodFillResult.Exclude) {
			return [];
		}
		const considerationList: HexTile[] = [initialTile];
		const returnList: HexTile[] = [];
		while (considerationList.length > 0) {
			const tile = considerationList.pop()!;
			returnList.push(tile);

			this.forNeighbors(tile.coord.x, tile.coord.y, this.m_tiles, (neighbor) => {
				if (neighbor && !neighbor.visited) {
					neighbor.visited = 1;
					const result = considerCallback(neighbor);
					switch (result) {
						case FloodFillResult.Include:
							considerationList.push(neighbor);
							break;
						case FloodFillResult.Halt:
							return returnList;
					}
				}
			});
		}
		return returnList;
	}

	clearVisited() {
		for (const row of this.m_tiles) {
			for (const tile of row) {
				tile.visited = 0;
			}
		}
	}

	getTiles(): readonly HexTile[][] {
		return this.m_tiles;
	}
}
